import sys

def main():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    iterator = iter(input_data)
    N = int(next(iterator))
    D = int(next(iterator))

    snakes = []
    for _ in range(N):
        t = int(next(iterator))
        l = int(next(iterator))
        snakes.append((t, l))

    for k in range(1, D + 1):
        max_w = 0
        for t, l in snakes:
            w = t * (l + k)
            if w > max_w:
                max_w = w
        print(max_w)

if __name__ == '__main__':
    main()
